def test_symmetry_around_equivalence():
    # Curve is nearly antisymmetric about pH 7 around V = 25.00 mL;
    # small residual asymmetry comes from dilution (total volume differs
    # by dv on either side), bounded by ~0.002 pH over these ranges.
    for dv in (0.10, 0.50, 2.00, 5.00):
        before = ph_at(25.00 - dv)
        after = ph_at(25.00 + dv)
        assert abs((before - 7.0) + (after - 7.0)) < 0.002

